function staysBounded(commands: string): boolean {
  const dx = [0, 1, 0, -1], dy = [1, 0, -1, 0];
  let x = 0, y = 0, d = 0;
  for (let pass = 0; pass < 4; pass++) {
    for (const c of commands) {
      if (c === "G") { x += dx[d]; y += dy[d]; }
      else if (c === "R") d = (d + 1) % 4;
      else d = (d + 3) % 4;
    }
  }
  return x === 0 && y === 0;
}

